// En la terminal: npm install pg
// db.js
import { Pool } from 'pg';
export const pool = new Pool({
  connectionString: process.env.DATABASE_URL
});
const result = await pool.query('SELECT now() AS servidor');
console.log(result.rows[0].servidor);

// .env local: DATABASE_URL=postgresql://usuario:clave@localhost:5432/tienda_dev
import 'dotenv/config';
import { pool } from './db.js';
const { rows } = await pool.query('SELECT current_database() AS base');
console.log(rows[0].base);

// Configuración compartida del pool.
const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 10, idleTimeoutMillis: 30000, connectionTimeoutMillis: 2000
});
const result = await pool.query('SELECT COUNT(*)::int AS total FROM productos');
console.log(result.rows[0].total);

// Ejemplo práctico:
const client = await pool.connect();
try {
  const result = await client.query('SELECT current_user AS usuario');
  console.log(result.rows[0].usuario);
} finally {
  client.release(); // Devolver la conexión al pool.
}

