// Ejemplo práctico:
const client = await pool.connect();
try {
  await client.query('BEGIN');
  await client.query('UPDATE cuentas SET saldo = saldo - $1 WHERE id = $2', [500, 1]);
  await client.query('UPDATE cuentas SET saldo = saldo + $1 WHERE id = $2', [500, 2]);
  await client.query('COMMIT');
} catch (error) {
  await client.query('ROLLBACK');
  throw error;
} finally {
  client.release();
}

// Ejemplo práctico:
const client = await pool.connect();
try {
  await client.query('BEGIN');
  const debit = await client.query(
    'UPDATE cuentas SET saldo = saldo - $1 WHERE id = $2 AND saldo >= $1 RETURNING id',
    [250, 1]
  );
  if (debit.rowCount !== 1) throw new Error('Saldo insuficiente');
  await client.query('COMMIT');
} catch (error) { await client.query('ROLLBACK'); throw error; }
finally { client.release(); }

// repositories/productos.js
import { pool } from '../db.js';
export async function listarProductos() {
  const { rows } = await pool.query(
    'SELECT id, nombre, precio FROM productos ORDER BY nombre'
  );
  return rows;
}

// routes/productos.js
import { Router } from 'express';
import { listarProductos } from '../repositories/productos.js';
const router = Router();
router.get('/productos', async (_req, res) => {
  const productos = await listarProductos();
  res.json(productos);
});
export default router;

